import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/cyclehire_w002.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Departures and Self-contained trips for each borough
data['StartBorough'] = data['StartBorough'].astype('category')
data['EndBorough'] = data['EndBorough'].astype('category')
boroughs = data['StartBorough'].unique()
departures = data.groupby('StartBorough')['Rental Id'].count().to_dict()
self_contained_trips = data[(data['StartBorough'] == data['EndBorough'])]['Rental Id'].count()

# Compute Arrival share for each borough
total_arrivals = data['EndBorough'].value_counts().to_dict()
arrival_share = {}
for borough in boroughs:
    arrival_share[borough] = total_arrivals[borough] / total_arrivals[boroughs].sum()

# Compute Expected self-contained trips for each borough
expected_self_contained_trips = {}
for borough in boroughs:
    expected_self_contained_trips[borough] = departures[borough] * arrival_share[borough]

# Compute Self-Containment Index for each borough
self_containment_index = {}
for borough in boroughs:
    self_containment_index[borough] = self_contained_trips / expected_self_contained_trips[borough]

# Identify neighboring boroughs for each borough
neighboring_boroughs = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighboring_boroughs:
        neighboring_boroughs[row['borough']] = []
    neighboring_boroughs[row['borough']].append(row['neighbor'])

# Compute Self-Containment Index for neighboring boroughs
self_containment_index_neighbors = {}
for borough in boroughs:
    self_containment_index_neighbors[borough] = {}
    for neighbor in neighboring_boroughs[borough]:
        self_containment_index_neighbors[borough][neighbor] = self_containment_index[neighbor]

# Determine if a borough is a HOT SPOT or COLD SPOT
hot_spots = {}
cold_spots = {}
for borough in boroughs:
    if self_containment_index[borough] > 1 and all(self_containment_index_neighbors[borough].values()) > 1:
        hot_spots[borough] = self_containment_index[borough]
    elif self_containment_index[borough] < 1 and all(self_containment_index_neighbors[borough].values()) < 1:
        cold_spots[borough] = self_containment_index[borough]

# Test for statistical significance
data_points_used = len(data)
test_statistic = np.mean(list(self_containment_index.values()))
p_value = np.random.permutation(500, size=(500, len(boroughs)))
p_value = np.mean(p_value, axis=0)
significance_measure = np.mean(p_value < test_statistic)

print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: BoroughName1 (HH, statistical method={test_statistic:.4f}), BoroughName2 (LL, statistical method={significance_measure:.4f})')

# List every borough that was identified as a HOT SPOT or COLD SPOT
if hot_spots:
    print(f'FINAL ANSWER: {list(hot_spots.keys())} (HH, statistical method={test_statistic:.4f})')
else:
    print(f'FINAL ANSWER: none')
